"""Builds CORE-PR-HANDOFF-v20.md from CORE-PR-HANDOFF-v19.md (improve, do not replace). Every replacement asserts that its old text occurs exactly
once, so a v19 text that moved makes the script stop instead of silently doing nothing. Numbers are read from the raw files at build time, not typed.
usage: python -I patch_v20_main.py <audit-r460 folder>"""
import re
import sys
from pathlib import Path

root = Path(sys.argv[1])
ev = root / "evidence-handoff-v20"
raw = ev / "raw"
t = (root / "CORE-PR-HANDOFF-v19.md").read_text(encoding="utf-8")


def rep(old, new):
    global t
    n = t.count(old)
    assert n == 1, f"expected 1 of, found {n}: {old[:90]!r}"
    t = t.replace(old, new)


def last(name, pat):
    txt = (raw / name).read_text(encoding="utf-8", errors="replace")
    m = [x for x in txt.splitlines() if re.search(pat, x)]
    return m[-1].strip() if m else "(line not found in " + name + ")"


pg1 = last("raw-pg-v20-run1.txt", r"^SUMMARY")
reg1 = last("raw-pg-v16-regress-on-v20-run1.txt", r"checks passed")
mut = last("raw-secdef-mutants-v20.txt", r"checks passed")
sp = last("raw-spell30-v20.txt", r"^SUMMARY")
sec = last("raw-secrets-v20-run1.txt", r"^SUMMARY")
pyt = last("raw-gate4-v20-pytest.txt", r"passed|failed|rc=") if (raw / "raw-gate4-v20-pytest.txt").exists() else "not run"
hs = {p.name: __import__("hashlib").sha256(p.read_bytes()).hexdigest() for p in sorted((ev / "held-sql").glob("*.sql"))}

